<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserConsentPurposes\Domain\ValueObject\UserConsentPurposesConsentPurposeVO;
use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurposeRef;

final class UserConsentPurposesConsentPurposeVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new ConsentPurposeRef('one');
        $ref = UserConsentPurposesConsentPurposeVO::from($value);
        $this->assertEquals(new ConsentPurposeRef('one'), $ref->value());
        $other = UserConsentPurposesConsentPurposeVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = UserConsentPurposesConsentPurposeVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = UserConsentPurposesConsentPurposeVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(UserConsentPurposesConsentPurposeVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = UserConsentPurposesConsentPurposeVO::from(new ConsentPurposeRef('one'));
        $same = UserConsentPurposesConsentPurposeVO::from(new ConsentPurposeRef('one'));
        $other = UserConsentPurposesConsentPurposeVO::from(new ConsentPurposeRef('other'));
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
}
